    tag='backup pre-polish')

# 2. The new CSS: keeps all existing rules, adds the polish layer.
CSS = r'''/* ============================================
   DESIGN — warm neutral polish (v1, 2026-07)
   Everything below is the "slick, not default" pass.
   To revert: replace the whole block with the backup at
   /home/dh_ieh64b/ronnylinder.me/custom-css.pre-polish-v1.txt
   ============================================ */

/* Warm neutral palette applied via CSS variables so tweaks are cheap */
:root {
    --page-bg:    #FAF8F5;   /* warm off-white body background */
    --panel-bg:   #FFFFFF;   /* article cards */
    --ink:        #2D2A26;   /* soft charcoal for body text */
    --ink-mute:   #6B6560;   /* metadata / bylines */
    --rule:       #E8E3DB;   /* warm hairline borders */
    --rule-soft:  #EFEAE2;   /* even softer sections */
    --accent:     #3E7B7E;   /* muted teal — links, buttons */
    --accent-dk:  #2E5F62;   /* teal hover */
    --private:    #A66E3F;   /* soft rust — private badge */
    --public:     #3E7B7E;   /* same teal — public badge */
}

/* Body + typography rhythm */
body,
body.ast-plain-container,
body.ast-page-builder-template {
    background-color: var(--page-bg);
    color: var(--ink);
}
body, p, .entry-content, .site-content {
    letter-spacing: 0.005em;   /* tiny bump — Hebrew reads clearer */
}
.entry-content p {
    color: var(--ink);
}
.entry-content h2,
.entry-content h3,
h1.entry-title,
h2.entry-title,
.ast-archive-title {
    color: var(--ink);
    letter-spacing: -0.005em;  /* tighten headings slightly */
    font-weight: 600;          /* was 700 by default — a touch lighter */
}

/* Links: muted teal, no underline until hover */
.entry-content a,
.ast-container a:not(.ast-button):not(.wp-block-button__link),
.site-title a,
.ronny-sidebar a,
.ronny-search-sort a,
.ronny-visibility-filter a {
    color: var(--accent);
    text-decoration: none;
    transition: color 0.12s ease;
}
.entry-content a:hover,
.ast-container a:not(.ast-button):not(.wp-block-button__link):hover,
.ronny-sidebar a:hover {
    color: var(--accent-dk);
    text-decoration: underline;
    text-underline-offset: 3px;
    text-decoration-thickness: 1px;
}

/* Header — cleaner background, hairline separator */
.ast-primary-header-bar,
.site-header,
header.site-header {
    background-color: var(--panel-bg) !important;
    border-bottom: 1px solid var(--rule);
    box-shadow: none !important;
}
.site-title a {
    color: var(--ink) !important;
    font-weight: 600;
}
.site-description {
    color: var(--ink-mute);
    font-weight: 400;
}

/* Article cards on listings — refined, not SaaS-like */
.blog article.post,
.archive article.post,
.search article.post {
    background: var(--panel-bg);
    border: 1px solid var(--rule);
    border-radius: 4px;               /* was 8px+, now barely visible */
    box-shadow: none !important;      /* was soft shadow — gone */
    padding: 1.5rem 1.75rem;
    margin-bottom: 1.25rem;
    transition: border-color 0.15s ease, transform 0.15s ease;
}
.blog article.post:hover,
.archive article.post:hover,
.search article.post:hover {
    border-color: #D6CFC2;
}
.blog article.post .entry-title,
.archive article.post .entry-title,
.search article.post .entry-title {
    font-size: 1.35rem;
    line-height: 1.4;
    margin: 0.35rem 0 0.5rem;
}
.blog article.post .entry-meta,
.archive article.post .entry-meta,
.search article.post .entry-meta {
    color: var(--ink-mute);
    font-size: 0.85rem;
}
.blog article.post .ast-excerpt-container,
.archive article.post .ast-excerpt-container,
.search article.post .ast-excerpt-container,
.blog article.post .entry-content,
.archive article.post .entry-content,
.search article.post .entry-content {
    color: var(--ink);
    line-height: 1.7;
}
.blog article.post .cat-links,
.archive article.post .cat-links,
.search article.post .cat-links {
    font-size: 0.8rem;
    color: var(--accent);
    text-transform: none;
    letter-spacing: 0.02em;
}

/* Private / public badges — refined, less "chip" */
.ronny-badge-private,
.ronny-title-tag--private {
    background: transparent !important;
    color: var(--private) !important;
    border: 1px solid var(--private);
    border-radius: 3px;
    padding: 0.05em 0.5em;
    font-size: 0.7em;
    font-weight: 600;
    letter-spacing: 0.03em;
    margin-inline-end: 0.5em;
    vertical-align: 0.15em;
}
.ronny-badge-public,
.ronny-title-tag--public {
    background: transparent !important;
    color: var(--public) !important;
    border: 1px solid var(--public);
    border-radius: 3px;
    padding: 0.05em 0.5em;
    font-size: 0.7em;
    font-weight: 600;
    letter-spacing: 0.03em;
    margin-inline-end: 0.5em;
    vertical-align: 0.15em;
}

/* Sidebar — warmer, no boxes */
.ronny-sidebar {
    background: transparent;
}
.ronny-sidebar-box {
    background: transparent;
    border: none;
    border-top: 1px solid var(--rule);
    border-radius: 0;
    padding: 1rem 0.25rem;
    box-shadow: none;
}
.ronny-sidebar-box:first-child { border-top: none; padding-top: 0; }
.ronny-sidebar-box > summary,
.ronny-sidebar-box > .ronny-sidebar-title {
    color: var(--ink);
    font-weight: 600;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    margin-bottom: 0.75rem;
}
.ronny-sidebar-box ul li a {
    padding: 0.2rem 0;
    color: var(--ink);
    font-size: 0.9rem;
    display: flex;
    justify-content: space-between;
    border-bottom: 1px dotted transparent;
    transition: border-color 0.12s ease, color 0.12s ease;
}
.ronny-sidebar-box ul li a:hover {
    color: var(--accent);
    border-bottom-color: var(--rule);
    text-decoration: none;
}
.ronny-sidebar-box ul li a > span:last-child {
    color: var(--ink-mute);
    font-size: 0.8rem;
    font-variant-numeric: tabular-nums;
}
.ronny-sidebar-box .is-active {
    font-weight: 700;
    color: var(--accent);
}

/* Search + filter bar (already there) — de-emphasize the borders */
.ronny-visibility-filter,
.ronny-search-sort {
    background: transparent;
    border: none;
    border-bottom: 1px solid var(--rule);
    border-radius: 0;
    padding: 0.75rem 0;
    margin-bottom: 1.25rem;
    color: var(--ink-mute);
    font-size: 0.9rem;
}
.ronny-visibility-filter a,
.ronny-search-sort a {
    padding: 0.35em 0.75em;
    border: 1px solid transparent;
    border-radius: 3px;
    transition: background 0.12s ease, border-color 0.12s ease;
}
